package main

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func coverageFixture(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	files := map[string]string{
		"go.mod":          "module example.com/project\n",
		"logic.go":        "package example\n",
		"bindings.go":     "// Code generated - DO NOT EDIT.\npackage example\n",
		"with_license.go": "// Copyright example\n\n// Code generated by a tool. DO NOT EDIT.\npackage example\n",
		"manual.go":       "package example\n// Code generated by a tool. DO NOT EDIT.\n",
	}
	for name, data := range files {
		if err := os.WriteFile(filepath.Join(root, name), []byte(data), 0600); err != nil {
			t.Fatal(err)
		}
	}
	return root
}

func TestFilterProfileExcludesGeneratedSources(t *testing.T) {
	root := coverageFixture(t)
	var input strings.Builder
	input.WriteString("\ufeffmode: atomic\r\n")
	for _, name := range []string{"logic.go", "bindings.go", "with_license.go", "manual.go", "missing.pb.go", "service_grpc.pb.go", "resources/generate-smart-binds/main.go", "resources/coverage-filter/main.go", "snetd/main.go"} {
		input.WriteString("example.com/project/" + name + ":1.1,2.1 1 0\r\n")
	}
	var output bytes.Buffer
	if err := filterProfile(root, strings.NewReader(input.String()), &output); err != nil {
		t.Fatal(err)
	}
	want := "mode: atomic\nexample.com/project/logic.go:1.1,2.1 1 0\nexample.com/project/manual.go:1.1,2.1 1 0\n"
	if output.String() != want {
		t.Fatalf("profile mismatch:\ngot: %s\nwant: %s", &output, want)
	}
}

func TestFilterProfilePreservesModesAndRepeatedRecords(t *testing.T) {
	for _, mode := range []string{"atomic", "count", "set"} {
		t.Run(mode, func(t *testing.T) {
			root := coverageFixture(t)
			profile := "mode: " + mode + "\nlogic.go:1.1,2.1 1 0\nlogic.go:1.1,2.1 1 7\n"
			var output bytes.Buffer
			if err := filterProfile(root, strings.NewReader(profile), &output); err != nil {
				t.Fatal(err)
			}
			if output.String() != profile {
				t.Fatalf("coverage records or counts changed: %s", &output)
			}
		})
	}
}

func TestWriteProfilePreservesPreviousReportOnFailure(t *testing.T) {
	for _, profile := range []string{
		"", "mode: invalid\n", "mode: atomic\nbroken record\n", "mode: atomic\n",
		"mode: atomic\nmissing.go:1.1,2.1 1 0\n",
		"mode: atomic\n../outside.go:1.1,2.1 1 0\n",
		"mode: atomic\nmissing.pb.go:1.1,2.1 1 0\n",
		"mode: atomic\nlogic.go:1.1,2.1 1 0\ninvalid\n",
	} {
		t.Run(profile, func(t *testing.T) {
			root := coverageFixture(t)
			input, output := filepath.Join(root, "raw.out"), filepath.Join(root, "filtered.out")
			if err := os.WriteFile(input, []byte(profile), 0600); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(output, []byte("previous report"), 0600); err != nil {
				t.Fatal(err)
			}
			if err := writeProfile(root, input, output); err == nil {
				t.Fatal("invalid profile accepted")
			}
			data, err := os.ReadFile(output)
			if err != nil {
				t.Fatal(err)
			}
			if string(data) != "previous report" {
				t.Fatalf("previous report overwritten: %s", data)
			}
			remaining, err := filepath.Glob(filepath.Join(root, ".coverage-filtered-*.out"))
			if err != nil || len(remaining) != 0 {
				t.Fatalf("temporary profile leaked: %v, %v", remaining, err)
			}
		})
	}
}

func TestWriteProfileReplacesExistingReport(t *testing.T) {
	root := coverageFixture(t)
	profile := "mode: count\nlogic.go:1.1,2.1 1 5\n"
	input, output := filepath.Join(root, "raw.out"), filepath.Join(root, "filtered.out")
	if err := os.WriteFile(input, []byte(profile), 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(output, []byte("previous report"), 0600); err != nil {
		t.Fatal(err)
	}
	if err := writeProfile(root, input, output); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(output)
	if err != nil {
		t.Fatal(err)
	}
	if string(data) != profile {
		t.Fatalf("profile mismatch: %s", data)
	}
}
